import EPFContributor
import EPFVerdict
import RFLProvenance
try:
    from typing import List, Optional
except:
    pass

class EPFT(object):

    # EPFT
    def __init__(
        self,
        EPF_ID = None,
        NAME = None,
        SCENARIO_ID = None,
        RFL_ID = None,
        ACI_ID = None,
        VICTIM_ENDPOINT_ID = None,
        LIMIT_KIND = 0,
        LIMIT_MODEL_NAME = None,
        VALUE_UNITS = None,
        SAMPLE_COUNT = 0,
        SAMPLE_EPOCHS = None,
        SAMPLE_VALUES = None,
        SAMPLE_LIMIT_VALUES = None,
        SAMPLE_MARGIN_DB = None,
        SAMPLE_EXCEEDS_LIMIT = None,
        CONTRIBUTORS = None,
        CDF_VALUES = None,
        CDF_PERCENT_TIME_EXCEEDED = None,
        VERDICT = None,
        PROVENANCE = None,
        COMPUTED_AT = 0,
        PRODUCER_ID = None,
        SIGNATURE = None,
        CANONICAL_JSON_SIGNATURE = None,
    ):
        self.EPF_ID = EPF_ID  # type: Optional[str]
        self.NAME = NAME  # type: Optional[str]
        self.SCENARIO_ID = SCENARIO_ID  # type: Optional[str]
        self.RFL_ID = RFL_ID  # type: Optional[str]
        self.ACI_ID = ACI_ID  # type: Optional[str]
        self.VICTIM_ENDPOINT_ID = VICTIM_ENDPOINT_ID  # type: Optional[str]
        self.LIMIT_KIND = LIMIT_KIND  # type: int
        self.LIMIT_MODEL_NAME = LIMIT_MODEL_NAME  # type: Optional[str]
        self.VALUE_UNITS = VALUE_UNITS  # type: Optional[str]
        self.SAMPLE_COUNT = SAMPLE_COUNT  # type: int
        self.SAMPLE_EPOCHS = SAMPLE_EPOCHS  # type: Optional[List[float]]
        self.SAMPLE_VALUES = SAMPLE_VALUES  # type: Optional[List[float]]
        self.SAMPLE_LIMIT_VALUES = SAMPLE_LIMIT_VALUES  # type: Optional[List[float]]
        self.SAMPLE_MARGIN_DB = SAMPLE_MARGIN_DB  # type: Optional[List[float]]
        self.SAMPLE_EXCEEDS_LIMIT = SAMPLE_EXCEEDS_LIMIT  # type: Optional[List[bool]]
        self.CONTRIBUTORS = CONTRIBUTORS  # type: Optional[List[EPFContributor.EPFContributorT]]
        self.CDF_VALUES = CDF_VALUES  # type: Optional[List[float]]
        self.CDF_PERCENT_TIME_EXCEEDED = CDF_PERCENT_TIME_EXCEEDED  # type: Optional[List[float]]
        self.VERDICT = VERDICT  # type: Optional[EPFVerdict.EPFVerdictT]
        self.PROVENANCE = PROVENANCE  # type: Optional[RFLProvenance.RFLProvenanceT]
        self.COMPUTED_AT = COMPUTED_AT  # type: int
        self.PRODUCER_ID = PRODUCER_ID  # type: Optional[str]
        self.SIGNATURE = SIGNATURE  # type: Optional[List[int]]
        self.CANONICAL_JSON_SIGNATURE = CANONICAL_JSON_SIGNATURE  # type: Optional[List[int]]

    @classmethod
    def InitFromBuf(cls, buf, pos):
        tmpEpf = EPF()
        tmpEpf.Init(buf, pos)
        return cls.InitFromObj(tmpEpf)

    @classmethod
    def InitFromPackedBuf(cls, buf, pos=0):
        n = flatbuffers.encode.Get(flatbuffers.packer.uoffset, buf, pos)
        return cls.InitFromBuf(buf, pos+n)

    @classmethod
    def InitFromObj(cls, tmpEpf):
        x = EPFT()
        x._UnPack(tmpEpf)
        return x

    # EPFT
    def _UnPack(self, EPF):
        if EPF is None:
            return
        self.EPF_ID = EPF.EPF_ID()
        self.NAME = EPF.NAME()
        self.SCENARIO_ID = EPF.SCENARIO_ID()
        self.RFL_ID = EPF.RFL_ID()
        self.ACI_ID = EPF.ACI_ID()
        self.VICTIM_ENDPOINT_ID = EPF.VICTIM_ENDPOINT_ID()
        self.LIMIT_KIND = EPF.LIMIT_KIND()
        self.LIMIT_MODEL_NAME = EPF.LIMIT_MODEL_NAME()
        self.VALUE_UNITS = EPF.VALUE_UNITS()
        self.SAMPLE_COUNT = EPF.SAMPLE_COUNT()
        if not EPF.SAMPLE_EPOCHSIsNone():
            if np is None:
                self.SAMPLE_EPOCHS = []
                for i in range(EPF.SAMPLE_EPOCHSLength()):
                    self.SAMPLE_EPOCHS.append(EPF.SAMPLE_EPOCHS(i))
            else:
                self.SAMPLE_EPOCHS = EPF.SAMPLE_EPOCHSAsNumpy()
        if not EPF.SAMPLE_VALUESIsNone():
            if np is None:
                self.SAMPLE_VALUES = []
                for i in range(EPF.SAMPLE_VALUESLength()):
                    self.SAMPLE_VALUES.append(EPF.SAMPLE_VALUES(i))
            else:
                self.SAMPLE_VALUES = EPF.SAMPLE_VALUESAsNumpy()
        if not EPF.SAMPLE_LIMIT_VALUESIsNone():
            if np is None:
                self.SAMPLE_LIMIT_VALUES = []
                for i in range(EPF.SAMPLE_LIMIT_VALUESLength()):
                    self.SAMPLE_LIMIT_VALUES.append(EPF.SAMPLE_LIMIT_VALUES(i))
            else:
                self.SAMPLE_LIMIT_VALUES = EPF.SAMPLE_LIMIT_VALUESAsNumpy()
        if not EPF.SAMPLE_MARGIN_DBIsNone():
            if np is None:
                self.SAMPLE_MARGIN_DB = []
                for i in range(EPF.SAMPLE_MARGIN_DBLength()):
                    self.SAMPLE_MARGIN_DB.append(EPF.SAMPLE_MARGIN_DB(i))
            else:
                self.SAMPLE_MARGIN_DB = EPF.SAMPLE_MARGIN_DBAsNumpy()
        if not EPF.SAMPLE_EXCEEDS_LIMITIsNone():
            if np is None:
                self.SAMPLE_EXCEEDS_LIMIT = []
                for i in range(EPF.SAMPLE_EXCEEDS_LIMITLength()):
                    self.SAMPLE_EXCEEDS_LIMIT.append(EPF.SAMPLE_EXCEEDS_LIMIT(i))
            else:
                self.SAMPLE_EXCEEDS_LIMIT = EPF.SAMPLE_EXCEEDS_LIMITAsNumpy()
        if not EPF.CONTRIBUTORSIsNone():
            self.CONTRIBUTORS = []
            for i in range(EPF.CONTRIBUTORSLength()):
                if EPF.CONTRIBUTORS(i) is None:
                    self.CONTRIBUTORS.append(None)
                else:
                    ePFContributor_ = EPFContributor.EPFContributorT.InitFromObj(EPF.CONTRIBUTORS(i))
                    self.CONTRIBUTORS.append(ePFContributor_)
        if not EPF.CDF_VALUESIsNone():
            if np is None:
                self.CDF_VALUES = []
                for i in range(EPF.CDF_VALUESLength()):
                    self.CDF_VALUES.append(EPF.CDF_VALUES(i))
            else:
                self.CDF_VALUES = EPF.CDF_VALUESAsNumpy()
        if not EPF.CDF_PERCENT_TIME_EXCEEDEDIsNone():
            if np is None:
                self.CDF_PERCENT_TIME_EXCEEDED = []
                for i in range(EPF.CDF_PERCENT_TIME_EXCEEDEDLength()):
                    self.CDF_PERCENT_TIME_EXCEEDED.append(EPF.CDF_PERCENT_TIME_EXCEEDED(i))
            else:
                self.CDF_PERCENT_TIME_EXCEEDED = EPF.CDF_PERCENT_TIME_EXCEEDEDAsNumpy()
        if EPF.VERDICT() is not None:
            self.VERDICT = EPFVerdict.EPFVerdictT.InitFromObj(EPF.VERDICT())
        if EPF.PROVENANCE() is not None:
            self.PROVENANCE = RFLProvenance.RFLProvenanceT.InitFromObj(EPF.PROVENANCE())
        self.COMPUTED_AT = EPF.COMPUTED_AT()
        self.PRODUCER_ID = EPF.PRODUCER_ID()
        if not EPF.SIGNATUREIsNone():
            if np is None:
                self.SIGNATURE = []
                for i in range(EPF.SIGNATURELength()):
                    self.SIGNATURE.append(EPF.SIGNATURE(i))
            else:
                self.SIGNATURE = EPF.SIGNATUREAsNumpy()
        if not EPF.CANONICAL_JSON_SIGNATUREIsNone():
            if np is None:
                self.CANONICAL_JSON_SIGNATURE = []
                for i in range(EPF.CANONICAL_JSON_SIGNATURELength()):
                    self.CANONICAL_JSON_SIGNATURE.append(EPF.CANONICAL_JSON_SIGNATURE(i))
            else:
                self.CANONICAL_JSON_SIGNATURE = EPF.CANONICAL_JSON_SIGNATUREAsNumpy()

    # EPFT
    def Pack(self, builder):
        if self.EPF_ID is not None:
            EPF_ID = builder.CreateString(self.EPF_ID)
        if self.NAME is not None:
            NAME = builder.CreateString(self.NAME)
        if self.SCENARIO_ID is not None:
            SCENARIO_ID = builder.CreateString(self.SCENARIO_ID)
        if self.RFL_ID is not None:
            RFL_ID = builder.CreateString(self.RFL_ID)
        if self.ACI_ID is not None:
            ACI_ID = builder.CreateString(self.ACI_ID)
        if self.VICTIM_ENDPOINT_ID is not None:
            VICTIM_ENDPOINT_ID = builder.CreateString(self.VICTIM_ENDPOINT_ID)
        if self.LIMIT_MODEL_NAME is not None:
            LIMIT_MODEL_NAME = builder.CreateString(self.LIMIT_MODEL_NAME)
        if self.VALUE_UNITS is not None:
            VALUE_UNITS = builder.CreateString(self.VALUE_UNITS)
        if self.SAMPLE_EPOCHS is not None:
            if np is not None and type(self.SAMPLE_EPOCHS) is np.ndarray:
                SAMPLE_EPOCHS = builder.CreateNumpyVector(self.SAMPLE_EPOCHS)
            else:
                EPFStartSAMPLE_EPOCHSVector(builder, len(self.SAMPLE_EPOCHS))
                for i in reversed(range(len(self.SAMPLE_EPOCHS))):
                    builder.PrependFloat64(self.SAMPLE_EPOCHS[i])
                SAMPLE_EPOCHS = builder.EndVector()
        if self.SAMPLE_VALUES is not None:
            if np is not None and type(self.SAMPLE_VALUES) is np.ndarray:
                SAMPLE_VALUES = builder.CreateNumpyVector(self.SAMPLE_VALUES)
            else:
                EPFStartSAMPLE_VALUESVector(builder, len(self.SAMPLE_VALUES))
                for i in reversed(range(len(self.SAMPLE_VALUES))):
                    builder.PrependFloat64(self.SAMPLE_VALUES[i])
                SAMPLE_VALUES = builder.EndVector()
        if self.SAMPLE_LIMIT_VALUES is not None:
            if np is not None and type(self.SAMPLE_LIMIT_VALUES) is np.ndarray:
                SAMPLE_LIMIT_VALUES = builder.CreateNumpyVector(self.SAMPLE_LIMIT_VALUES)
            else:
                EPFStartSAMPLE_LIMIT_VALUESVector(builder, len(self.SAMPLE_LIMIT_VALUES))
                for i in reversed(range(len(self.SAMPLE_LIMIT_VALUES))):
                    builder.PrependFloat64(self.SAMPLE_LIMIT_VALUES[i])
                SAMPLE_LIMIT_VALUES = builder.EndVector()
        if self.SAMPLE_MARGIN_DB is not None:
            if np is not None and type(self.SAMPLE_MARGIN_DB) is np.ndarray:
                SAMPLE_MARGIN_DB = builder.CreateNumpyVector(self.SAMPLE_MARGIN_DB)
            else:
                EPFStartSAMPLE_MARGIN_DBVector(builder, len(self.SAMPLE_MARGIN_DB))
                for i in reversed(range(len(self.SAMPLE_MARGIN_DB))):
                    builder.PrependFloat64(self.SAMPLE_MARGIN_DB[i])
                SAMPLE_MARGIN_DB = builder.EndVector()
        if self.SAMPLE_EXCEEDS_LIMIT is not None:
            if np is not None and type(self.SAMPLE_EXCEEDS_LIMIT) is np.ndarray:
                SAMPLE_EXCEEDS_LIMIT = builder.CreateNumpyVector(self.SAMPLE_EXCEEDS_LIMIT)
            else:
                EPFStartSAMPLE_EXCEEDS_LIMITVector(builder, len(self.SAMPLE_EXCEEDS_LIMIT))
                for i in reversed(range(len(self.SAMPLE_EXCEEDS_LIMIT))):
                    builder.PrependBool(self.SAMPLE_EXCEEDS_LIMIT[i])
                SAMPLE_EXCEEDS_LIMIT = builder.EndVector()
        if self.CONTRIBUTORS is not None:
            CONTRIBUTORSlist = []
            for i in range(len(self.CONTRIBUTORS)):
                CONTRIBUTORSlist.append(self.CONTRIBUTORS[i].Pack(builder))
            EPFStartCONTRIBUTORSVector(builder, len(self.CONTRIBUTORS))
            for i in reversed(range(len(self.CONTRIBUTORS))):
                builder.PrependUOffsetTRelative(CONTRIBUTORSlist[i])
            CONTRIBUTORS = builder.EndVector()
        if self.CDF_VALUES is not None:
            if np is not None and type(self.CDF_VALUES) is np.ndarray:
                CDF_VALUES = builder.CreateNumpyVector(self.CDF_VALUES)
            else:
                EPFStartCDF_VALUESVector(builder, len(self.CDF_VALUES))
                for i in reversed(range(len(self.CDF_VALUES))):
                    builder.PrependFloat64(self.CDF_VALUES[i])
                CDF_VALUES = builder.EndVector()
        if self.CDF_PERCENT_TIME_EXCEEDED is not None:
            if np is not None and type(self.CDF_PERCENT_TIME_EXCEEDED) is np.ndarray:
                CDF_PERCENT_TIME_EXCEEDED = builder.CreateNumpyVector(self.CDF_PERCENT_TIME_EXCEEDED)
            else:
                EPFStartCDF_PERCENT_TIME_EXCEEDEDVector(builder, len(self.CDF_PERCENT_TIME_EXCEEDED))
                for i in reversed(range(len(self.CDF_PERCENT_TIME_EXCEEDED))):
                    builder.PrependFloat64(self.CDF_PERCENT_TIME_EXCEEDED[i])
                CDF_PERCENT_TIME_EXCEEDED = builder.EndVector()
        if self.VERDICT is not None:
            VERDICT = self.VERDICT.Pack(builder)
        if self.PROVENANCE is not None:
            PROVENANCE = self.PROVENANCE.Pack(builder)
        if self.PRODUCER_ID is not None:
            PRODUCER_ID = builder.CreateString(self.PRODUCER_ID)
        if self.SIGNATURE is not None:
            if np is not None and type(self.SIGNATURE) is np.ndarray:
                SIGNATURE = builder.CreateNumpyVector(self.SIGNATURE)
            else:
                EPFStartSIGNATUREVector(builder, len(self.SIGNATURE))
                for i in reversed(range(len(self.SIGNATURE))):
                    builder.PrependUint8(self.SIGNATURE[i])
                SIGNATURE = builder.EndVector()
        if self.CANONICAL_JSON_SIGNATURE is not None:
            if np is not None and type(self.CANONICAL_JSON_SIGNATURE) is np.ndarray:
                CANONICAL_JSON_SIGNATURE = builder.CreateNumpyVector(self.CANONICAL_JSON_SIGNATURE)
            else:
                EPFStartCANONICAL_JSON_SIGNATUREVector(builder, len(self.CANONICAL_JSON_SIGNATURE))
                for i in reversed(range(len(self.CANONICAL_JSON_SIGNATURE))):
                    builder.PrependUint8(self.CANONICAL_JSON_SIGNATURE[i])
                CANONICAL_JSON_SIGNATURE = builder.EndVector()
        EPFStart(builder)
        if self.EPF_ID is not None:
            EPFAddEPF_ID(builder, EPF_ID)
        if self.NAME is not None:
            EPFAddNAME(builder, NAME)
        if self.SCENARIO_ID is not None:
            EPFAddSCENARIO_ID(builder, SCENARIO_ID)
        if self.RFL_ID is not None:
            EPFAddRFL_ID(builder, RFL_ID)
        if self.ACI_ID is not None:
            EPFAddACI_ID(builder, ACI_ID)
        if self.VICTIM_ENDPOINT_ID is not None:
            EPFAddVICTIM_ENDPOINT_ID(builder, VICTIM_ENDPOINT_ID)
        EPFAddLIMIT_KIND(builder, self.LIMIT_KIND)
        if self.LIMIT_MODEL_NAME is not None:
            EPFAddLIMIT_MODEL_NAME(builder, LIMIT_MODEL_NAME)
        if self.VALUE_UNITS is not None:
            EPFAddVALUE_UNITS(builder, VALUE_UNITS)
        EPFAddSAMPLE_COUNT(builder, self.SAMPLE_COUNT)
        if self.SAMPLE_EPOCHS is not None:
            EPFAddSAMPLE_EPOCHS(builder, SAMPLE_EPOCHS)
        if self.SAMPLE_VALUES is not None:
            EPFAddSAMPLE_VALUES(builder, SAMPLE_VALUES)
        if self.SAMPLE_LIMIT_VALUES is not None:
            EPFAddSAMPLE_LIMIT_VALUES(builder, SAMPLE_LIMIT_VALUES)
        if self.SAMPLE_MARGIN_DB is not None:
            EPFAddSAMPLE_MARGIN_DB(builder, SAMPLE_MARGIN_DB)
        if self.SAMPLE_EXCEEDS_LIMIT is not None:
            EPFAddSAMPLE_EXCEEDS_LIMIT(builder, SAMPLE_EXCEEDS_LIMIT)
        if self.CONTRIBUTORS is not None:
            EPFAddCONTRIBUTORS(builder, CONTRIBUTORS)
        if self.CDF_VALUES is not None:
            EPFAddCDF_VALUES(builder, CDF_VALUES)
        if self.CDF_PERCENT_TIME_EXCEEDED is not None:
            EPFAddCDF_PERCENT_TIME_EXCEEDED(builder, CDF_PERCENT_TIME_EXCEEDED)
        if self.VERDICT is not None:
            EPFAddVERDICT(builder, VERDICT)
        if self.PROVENANCE is not None:
            EPFAddPROVENANCE(builder, PROVENANCE)
        EPFAddCOMPUTED_AT(builder, self.COMPUTED_AT)
        if self.PRODUCER_ID is not None:
            EPFAddPRODUCER_ID(builder, PRODUCER_ID)
        if self.SIGNATURE is not None:
            EPFAddSIGNATURE(builder, SIGNATURE)
        if self.CANONICAL_JSON_SIGNATURE is not None:
            EPFAddCANONICAL_JSON_SIGNATURE(builder, CANONICAL_JSON_SIGNATURE)
        EPF = EPFEnd(builder)
        return EPF
